(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('word-counter-plugin', {
    meta: {
      name: 'Word Counter Plugin',
      type: 'Plugin',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Display word count for each card'
    },

    countWords(text) {
      if (!text || text.trim() === '') return 0;
      return text.trim().split(/\s+/).length;
    },

    onCardRender(ctx, card, element) {
      const wordCount = this.countWords(card.body);

      // Create word count badge
      const badge = document.createElement('span');
      badge.className = 'word-count-badge';
      badge.textContent = `${wordCount} word${wordCount !== 1 ? 's' : ''}`;
      badge.title = 'Word count';

      // Add to card title area
      const titleElement = element.querySelector('.card-title');
      if (titleElement && !titleElement.querySelector('.word-count-badge')) {
        titleElement.appendChild(badge);
      }
    },

    async onCardSave(ctx, card, saveInfo) {
      // Store word count in modsData
      const wordCount = this.countWords(card.body);

      if (!card.modsData) card.modsData = {};
      if (!card.modsData[ctx.modId]) card.modsData[ctx.modId] = {};

      card.modsData[ctx.modId].wordCount = wordCount;
      card.modsData[ctx.modId].lastCounted = Date.now();

      await ctx.utils.updateCard(card.id, { modsData: card.modsData });
    }
  });
})();

